package com.example.data

import com.example.data.model.QuizQuestion

object QuizGenerator {

    fun generateQuiz(subjectId: String, topicTitle: String, pdfTitle: String): List<QuizQuestion> {
        val questions = mutableListOf<QuizQuestion>()

        val bank = when (subjectId) {
            "computing_fundamental" -> computingQuestions(topicTitle)
            "discrete_mathematics" -> discreteQuestions(topicTitle)
            "cpp_basics" -> cppQuestions(topicTitle)
            "oop_java" -> oopQuestions(topicTitle)
            "calculus" -> calculusQuestions(topicTitle)
            "internet_technology" -> itQuestions(topicTitle)
            "operating_systems" -> osQuestions(topicTitle)
            "probability_statistics" -> probQuestions(topicTitle)
            else -> genericQuestions(subjectId, topicTitle)
        }

        // Take up to 20 MCQs
        val mcqs = bank.filter { !it.isEssay }.take(20)
        // If bank has fewer than 20 MCQs, supplement with generated topic-specific MCQs
        var currentId = 1
        for (q in mcqs) {
            questions.add(q.copy(id = currentId++))
        }
        while (questions.size < 20) {
            val qIndex = questions.size + 1
            questions.add(
                QuizQuestion(
                    id = currentId++,
                    text = "سؤال $qIndex: ما هو المفهوم الأساسي المرتبط بـ ($topicTitle) في هذا الجزء؟",
                    options = listOf(
                        "التعريف والخصائص العامة للموضوع",
                        "تجاهل خطوات المعالجة والتحليل",
                        "الاستغناء عن الشروط المنطقية",
                        "إلغاء المعالجة التسلسلية"
                    ),
                    correctIndex = 0,
                    explanation = "يركز هذا السؤال على فهم القواعد المباشرة والتطبيقية لـ $topicTitle."
                )
            )
        }

        // Take 2 Essay questions
        val essays = bank.filter { it.isEssay }.take(2)
        if (essays.size == 2) {
            questions.add(essays[0].copy(id = currentId++))
            questions.add(essays[1].copy(id = currentId++))
        } else {
            questions.add(
                QuizQuestion(
                    id = currentId++,
                    text = "سؤال مقالي 1: اشرح بالتفصيل الفكرة الجوهرية ومراحل العمل في ($topicTitle) مع ذكر مثال تطبيقي.",
                    isEssay = true,
                    modelAnswer = "تتضمن الفكرة الجوهرية فهم المكونات، المدخلات، العمليات الوسيطة، والمخرجات النهائية وفق معايير المحتوى الموضح في $pdfTitle."
                )
            )
            questions.add(
                QuizQuestion(
                    id = currentId++,
                    text = "سؤال مقالي 2: قارن بين حالتين مختلفتين لتطبيق ($topicTitle) موضحاً الفروق وأفضل الممارسات البرمجية والتحليلية.",
                    isEssay = true,
                    modelAnswer = "تعتمد المقارنة على تقييم الكفاءة الزمنية والمساحية والدقة في المعالجة حسب مبادئ المادة."
                )
            )
        }

        return questions
    }

